/// Presets for PHP web applications.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum PhpPreset {
    #[default]
    Generic,
    Wordpress,
    Laravel,
    Custom,
}

impl PhpPreset {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Generic => "generic",
            Self::Wordpress => "wordpress",
            Self::Laravel => "laravel",
            Self::Custom => "custom",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        match s.to_ascii_lowercase().as_str() {
            "generic" | "default" | "standard" => Some(Self::Generic),
            "wordpress" | "wp" => Some(Self::Wordpress),
            "laravel" => Some(Self::Laravel),
            "custom" => Some(Self::Custom),
            _ => None,
        }
    }
}

impl fmt::Display for PhpPreset {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.as_str())
    }
}

fn default_true() -> bool {
    true
}

/// Optional FastCGI microcaching configuration.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct FastCgiCacheConfig {
    pub enabled: bool,
    #[serde(default)]
    pub zone_name: Option<String>,
    #[serde(default)]
    pub valid_time: Option<String>,
    #[serde(default = "default_true")]
    pub use_stale: bool,
    #[serde(default)]
    pub custom_bypass_cookies: Vec<String>,
}

impl Default for FastCgiCacheConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            zone_name: Some("panel_php_cache".to_string()),
            valid_time: Some("60m".to_string()),
            use_stale: true,
            custom_bypass_cookies: vec![],
        }
    }
}

impl FastCgiCacheConfig {
    pub fn enabled_default() -> Self {
        Self {
            enabled: true,
            ..Default::default()
        }
    }
}

