pub struct NginxTemplateRenderer {
    env: Environment<'static>,
}

impl Default for NginxTemplateRenderer {
    fn default() -> Self {
        Self::new()
    }
}

impl NginxTemplateRenderer {
    pub fn new() -> Self {
        let mut env = Environment::new();
        let templates = [
            ("vhost_static", STATIC_VHOST_TEMPLATE),
            ("vhost_php", PHP_VHOST_TEMPLATE),
            ("vhost_nodejs", NODEJS_VHOST_TEMPLATE),
            ("vhost_python", PYTHON_VHOST_TEMPLATE),
        ];
        for (name, source) in templates {
            if let Err(e) = env.add_template(name, source) {
                tracing::error!("Failed to register {name} template: {e}");
            }
        }
        Self { env }
    }

    /// Renders a static website virtual host after validating all inputs against injection attacks.
    pub fn render_static(&self, ctx: &StaticVhostContext) -> Result<String, WebserverError> {
        validate_vhost_inputs(ctx)?;

        // Normalize paths for Nginx directives
        let mut normalized = ctx.clone();
        normalized.docroot = normalized.docroot.replace('\\', "/");
        normalized.log_dir = normalized.log_dir.replace('\\', "/");
        normalized.snippets_dir = normalized.snippets_dir.replace('\\', "/");
        if let Some(ref cert) = normalized.ssl_cert {
            normalized.ssl_cert = Some(cert.replace('\\', "/"));
        }
        if let Some(ref key) = normalized.ssl_key {
            normalized.ssl_key = Some(key.replace('\\', "/"));
        }

        let tmpl = self
            .env
            .get_template("vhost_static")
            .map_err(|e| WebserverError::Template(e.to_string()))?;

        tmpl.render(&normalized)
            .map_err(|e| WebserverError::Template(e.to_string()))
    }

    /// Renders a PHP website virtual host after validating all inputs against injection attacks.
    pub fn render_php(&self, ctx: &PhpVhostContext) -> Result<String, WebserverError> {
        validate_php_vhost_inputs(ctx)?;

        let mut normalized = ctx.clone();
        normalized.docroot = normalized.docroot.replace('\\', "/");
        normalized.log_dir = normalized.log_dir.replace('\\', "/");
        normalized.snippets_dir = normalized.snippets_dir.replace('\\', "/");
        if let Some(ref cert) = normalized.ssl_cert {
            normalized.ssl_cert = Some(cert.replace('\\', "/"));
        }
        if let Some(ref key) = normalized.ssl_key {
            normalized.ssl_key = Some(key.replace('\\', "/"));
        }
        normalized.fpm_socket = normalized.fpm_socket.replace('\\', "/");
        if !normalized.fpm_socket.starts_with("unix:") && normalized.fpm_socket.starts_with('/') {
            normalized.fpm_socket = format!("unix:{}", normalized.fpm_socket);
        }

        let tmpl = self
            .env
            .get_template("vhost_php")
            .map_err(|e| WebserverError::Template(e.to_string()))?;

        tmpl.render(&normalized)
            .map_err(|e| WebserverError::Template(e.to_string()))
    }

    /// Renders a Node.js reverse proxy virtual host after validating all inputs against injection attacks.
    pub fn render_nodejs(&self, ctx: &NodejsVhostContext) -> Result<String, WebserverError> {
        validate_nodejs_vhost_inputs(ctx)?;

        let mut normalized = ctx.clone();
        if let Some(ref doc) = normalized.docroot {
            normalized.docroot = Some(doc.replace('\\', "/"));
        }
        normalized.log_dir = normalized.log_dir.replace('\\', "/");
        normalized.snippets_dir = normalized.snippets_dir.replace('\\', "/");
        if let Some(ref cert) = normalized.ssl_cert {
            normalized.ssl_cert = Some(cert.replace('\\', "/"));
        }
        if let Some(ref key) = normalized.ssl_key {
            normalized.ssl_key = Some(key.replace('\\', "/"));
        }

        let tmpl = self
            .env
            .get_template("vhost_nodejs")
            .map_err(|e| WebserverError::Template(e.to_string()))?;

        tmpl.render(&normalized)
            .map_err(|e| WebserverError::Template(e.to_string()))
    }

    /// Renders a Python WSGI/ASGI virtual host after validating all inputs against injection attacks.
    pub fn render_python(&self, ctx: &PythonVhostContext) -> Result<String, WebserverError> {
        validate_python_vhost_inputs(ctx)?;

        let mut normalized = ctx.clone();
        normalized.log_dir = normalized.log_dir.replace('\\', "/");
        normalized.snippets_dir = normalized.snippets_dir.replace('\\', "/");
        if let Some(ref cert) = normalized.ssl_cert {
            normalized.ssl_cert = Some(cert.replace('\\', "/"));
        }
        if let Some(ref key) = normalized.ssl_key {
            normalized.ssl_key = Some(key.replace('\\', "/"));
        }

        let mut sock = normalized.unix_socket.replace('\\', "/");
        if let Some(rest) = sock.strip_prefix("unix:") {
            sock = rest.to_string();
        }
        normalized.unix_socket = sock;

        if let (Some(url), Some(dir)) = (&normalized.static_url, &normalized.static_dir) {
            let mut d = dir.replace('\\', "/");
            if url.ends_with('/') && !d.ends_with('/') {
                d.push('/');
            }
            normalized.static_dir = Some(d);
        }

        if let (Some(url), Some(dir)) = (&normalized.media_url, &normalized.media_dir) {
            let mut d = dir.replace('\\', "/");
            if url.ends_with('/') && !d.ends_with('/') {
                d.push('/');
            }
            normalized.media_dir = Some(d);
        }

        let tmpl = self
            .env
            .get_template("vhost_python")
            .map_err(|e| WebserverError::Template(e.to_string()))?;

        tmpl.render(&normalized)
            .map_err(|e| WebserverError::Template(e.to_string()))
    }
}

/// Strictly validates Node.js virtual host context inputs.
pub fn validate_nodejs_vhost_inputs(ctx: &NodejsVhostContext) -> Result<(), WebserverError> {
    if ctx.site_id.trim().is_empty() {
        return Err(WebserverError::SecurityViolation(
            "site_id cannot be empty".to_string(),
        ));
    }
    for ch in ctx.site_id.chars() {
        if !ch.is_alphanumeric() && ch != '-' && ch != '_' {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid character '{ch}' in site_id '{}'",
                ctx.site_id
            )));
        }
    }

    validate_domain_input(&ctx.primary_domain)?;
    for alias in &ctx.alias_domains {
        validate_domain_input(alias)?;
    }

    if let Some(ref docroot) = ctx.docroot {
        validate_path_input(docroot, "docroot")?;
    }
    validate_path_input(&ctx.log_dir, "log_dir")?;
    validate_path_input(&ctx.snippets_dir, "snippets_dir")?;

    if let Some(ref cert) = ctx.ssl_cert {
        validate_path_input(cert, "ssl_cert")?;
    }
    if let Some(ref key) = ctx.ssl_key {
        validate_path_input(key, "ssl_key")?;
    }

    validate_nodejs_upstream_url(&ctx.upstream_url)?;

    for h in &ctx.custom_headers {
        if !h
            .name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid HTTP header name: '{}'",
                h.name
            )));
        }
        if h.value
            .chars()
            .any(|c| c == '\n' || c == '\r' || c == '\0' || c == '"' || c == ';')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid characters in HTTP header value: '{}'",
                h.value
            )));
        }
    }

    for r in &ctx.redirects {
        validate_domain_input(&r.domain)?;
        validate_redirect_target(&r.target)?;
        if r.status_code != 301
            && r.status_code != 302
            && r.status_code != 307
            && r.status_code != 308
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid redirect status code: {}",
                r.status_code
            )));
        }
    }

    Ok(())
}

fn validate_nodejs_upstream_url(upstream: &str) -> Result<(), WebserverError> {
    const FORBIDDEN_UPSTREAM_CHARS: &[char] =
        &[';', '{', '}', '\n', '\r', '\0', ' ', '\t', '"', '\''];
    for ch in FORBIDDEN_UPSTREAM_CHARS {
        if upstream.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Forbidden character '{ch}' in upstream_url"
            )));
        }
    }

    // SSRF Guard: prevent cloud metadata IP traversal
    if upstream.contains("169.254.") {
        return Err(WebserverError::SecurityViolation(
            "Cloud metadata IP address is forbidden in upstream_url".to_string(),
        ));
    }

    // Must be loopback or unix socket
    if upstream.starts_with("http://127.0.0.1:")
        || upstream.starts_with("http://[::1]:")
        || upstream.starts_with("http://localhost:")
        || upstream.starts_with("http://unix:")
    {
        Ok(())
    } else {
        Err(WebserverError::SecurityViolation(format!(
            "Upstream URL '{}' must target local loopback (127.0.0.1 / [::1]) or unix socket",
            upstream
        )))
    }
}

/// Strictly validates Python virtual host context inputs.
pub fn validate_python_vhost_inputs(ctx: &PythonVhostContext) -> Result<(), WebserverError> {
    if ctx.site_id.trim().is_empty() {
        return Err(WebserverError::SecurityViolation(
            "site_id cannot be empty".to_string(),
        ));
    }
    for ch in ctx.site_id.chars() {
        if !ch.is_alphanumeric() && ch != '-' && ch != '_' {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid character '{ch}' in site_id '{}'",
                ctx.site_id
            )));
        }
    }

    validate_domain_input(&ctx.primary_domain)?;
    for alias in &ctx.alias_domains {
        validate_domain_input(alias)?;
    }

    validate_path_input(&ctx.log_dir, "log_dir")?;
    validate_path_input(&ctx.snippets_dir, "snippets_dir")?;

    if let Some(ref cert) = ctx.ssl_cert {
        validate_path_input(cert, "ssl_cert")?;
    }
    if let Some(ref key) = ctx.ssl_key {
        validate_path_input(key, "ssl_key")?;
    }

    validate_unix_socket_path(&ctx.unix_socket)?;

    if let Some(ref static_dir) = ctx.static_dir {
        validate_path_input(static_dir, "static_dir")?;
    }
    if let Some(ref static_url) = ctx.static_url {
        validate_location_url(static_url, "static_url")?;
    }

    if let Some(ref media_dir) = ctx.media_dir {
        validate_path_input(media_dir, "media_dir")?;
    }
    if let Some(ref media_url) = ctx.media_url {
        validate_location_url(media_url, "media_url")?;
    }

    for h in &ctx.custom_headers {
        if !h
            .name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid HTTP header name: '{}'",
                h.name
            )));
        }
        if h.value
            .chars()
            .any(|c| c == '\n' || c == '\r' || c == '\0' || c == '"' || c == ';')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid characters in HTTP header value: '{}'",
                h.value
            )));
        }
    }

    for r in &ctx.redirects {
        validate_domain_input(&r.domain)?;
        validate_redirect_target(&r.target)?;
        if r.status_code != 301
            && r.status_code != 302
            && r.status_code != 307
            && r.status_code != 308
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid redirect status code: {}",
                r.status_code
            )));
        }
    }

    Ok(())
}

fn validate_unix_socket_path(socket: &str) -> Result<(), WebserverError> {
    const FORBIDDEN_SOCKET_CHARS: &[char] =
        &[';', '{', '}', '\n', '\r', '\0', ' ', '\t', '"', '\''];
    for ch in FORBIDDEN_SOCKET_CHARS {
        if socket.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Forbidden character '{ch}' in unix socket path"
            )));
        }
    }

    let clean = socket.strip_prefix("unix:").unwrap_or(socket);
    if clean.is_empty() {
        return Err(WebserverError::SecurityViolation(
            "Unix socket path cannot be empty".to_string(),
        ));
    }
    if !clean.starts_with('/') {
        return Err(WebserverError::SecurityViolation(format!(
            "Unix socket path '{}' must be an absolute path starting with '/'",
            clean
        )));
    }
    if clean.contains("..") {
        return Err(WebserverError::SecurityViolation(
            "Unix socket path must not contain '..'".to_string(),
        ));
    }

    Ok(())
}

fn validate_location_url(url: &str, field_name: &str) -> Result<(), WebserverError> {
    const FORBIDDEN_URL_CHARS: &[char] = &[';', '{', '}', '\n', '\r', '\0', ' ', '\t', '"', '\''];
    for ch in FORBIDDEN_URL_CHARS {
        if url.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Forbidden character '{ch}' in {field_name}"
            )));
        }
    }
    if !url.starts_with('/') {
        return Err(WebserverError::SecurityViolation(format!(
            "{field_name} must start with '/'"
        )));
    }
    if url.contains("..") {
        return Err(WebserverError::SecurityViolation(format!(
            "{field_name} must not contain '..'"
        )));
    }
    Ok(())
}

/// Strictly validates all context fields against config injection attacks.
pub fn validate_vhost_inputs(ctx: &StaticVhostContext) -> Result<(), WebserverError> {
    // 1. Site ID validation
    if ctx.site_id.trim().is_empty() {
        return Err(WebserverError::SecurityViolation(
            "site_id cannot be empty".to_string(),
        ));
    }
    for ch in ctx.site_id.chars() {
        if !ch.is_alphanumeric() && ch != '-' && ch != '_' {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid character '{ch}' in site_id '{}'",
                ctx.site_id
            )));
        }
    }

    // 2. Domain validation (RFC 1034/1035 + Punycode IDN + forbidden chars)
    validate_domain_input(&ctx.primary_domain)?;
    for alias in &ctx.alias_domains {
        validate_domain_input(alias)?;
    }

    // 3. Docroot validation
    validate_path_input(&ctx.docroot, "docroot")?;
    validate_path_input(&ctx.log_dir, "log_dir")?;
    validate_path_input(&ctx.snippets_dir, "snippets_dir")?;

    if let Some(ref cert) = ctx.ssl_cert {
        validate_path_input(cert, "ssl_cert")?;
    }
    if let Some(ref key) = ctx.ssl_key {
        validate_path_input(key, "ssl_key")?;
    }

    // 4. Custom headers validation
    for h in &ctx.custom_headers {
        if !h
            .name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid HTTP header name: '{}'",
                h.name
            )));
        }
        if h.value
            .chars()
            .any(|c| c == '\n' || c == '\r' || c == '\0' || c == '"' || c == ';')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid characters in HTTP header value: '{}'",
                h.value
            )));
        }
    }

    // 5. Redirects validation
    for r in &ctx.redirects {
        validate_domain_input(&r.domain)?;
        validate_redirect_target(&r.target)?;
        if r.status_code != 301
            && r.status_code != 302
            && r.status_code != 307
            && r.status_code != 308
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid redirect status code: {}",
                r.status_code
            )));
        }
    }

    Ok(())
}

fn validate_redirect_target(target: &str) -> Result<(), WebserverError> {
    const FORBIDDEN_CHARS: &[char] = &[
        ';', '{', '}', '\n', '\r', '\0', '"', '\'', ' ', '\t', '<', '>',
    ];
    for ch in FORBIDDEN_CHARS {
        if target.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Redirect target '{target}' contains forbidden character '{ch}'"
            )));
        }
    }

    if !target.starts_with("http://")
        && !target.starts_with("https://")
        && !target.starts_with('/')
        && !target.starts_with("$scheme://")
    {
        return Err(WebserverError::SecurityViolation(format!(
            "Redirect target '{target}' must start with http://, https://, /, or $scheme://"
        )));
    }

    for (idx, _) in target.match_indices('$') {
        let remainder = &target[idx..];
        let allowed = remainder.starts_with("$request_uri")
            || remainder.starts_with("$host")
            || remainder.starts_with("$scheme");
        if !allowed {
            return Err(WebserverError::SecurityViolation(format!(
                "Unrecognized or forbidden variable in redirect target '{target}'"
            )));
        }
    }

    Ok(())
}

fn validate_domain_input(raw: &str) -> Result<(), WebserverError> {
    // Check forbidden control & Nginx configuration characters
    const FORBIDDEN_CHARS: &[char] = &[';', '{', '}', '$', '\n', '\r', '\0', '"', ' ', '\t'];
    for ch in FORBIDDEN_CHARS {
        if raw.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Domain '{raw}' contains forbidden character '{ch}'"
            )));
        }
    }

    // Parse and validate via DomainName (RFC compliance & IDN normalization)
    DomainName::parse(raw)
        .map_err(|e| WebserverError::SecurityViolation(format!("Invalid domain '{raw}': {e}")))?;

    Ok(())
}

fn validate_path_input(raw: &str, field_name: &str) -> Result<(), WebserverError> {
    if raw.trim().is_empty() {
        return Err(WebserverError::SecurityViolation(format!(
            "{field_name} cannot be empty"
        )));
    }

    const FORBIDDEN_CHARS: &[char] = &[';', '{', '}', '$', '\n', '\r', '\0', '"'];
    for ch in FORBIDDEN_CHARS {
        if raw.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Path in {field_name} contains forbidden character '{ch}'"
            )));
        }
    }

    Ok(())
}

/// Strictly validates all PHP virtual host context fields against config injection attacks.
#[allow(clippy::collapsible_if)]
pub fn validate_php_vhost_inputs(ctx: &PhpVhostContext) -> Result<(), WebserverError> {
    // 1. Site ID validation
    if ctx.site_id.trim().is_empty() {
        return Err(WebserverError::SecurityViolation(
            "site_id cannot be empty".to_string(),
        ));
    }
    for ch in ctx.site_id.chars() {
        if !ch.is_alphanumeric() && ch != '-' && ch != '_' {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid character '{ch}' in site_id '{}'",
                ctx.site_id
            )));
        }
    }

    // 2. Domain validation
    validate_domain_input(&ctx.primary_domain)?;
    for alias in &ctx.alias_domains {
        validate_domain_input(alias)?;
    }

    // 3. Path validation
    validate_path_input(&ctx.docroot, "docroot")?;
    validate_path_input(&ctx.log_dir, "log_dir")?;
    validate_path_input(&ctx.snippets_dir, "snippets_dir")?;

    if let Some(ref cert) = ctx.ssl_cert {
        validate_path_input(cert, "ssl_cert")?;
    }
    if let Some(ref key) = ctx.ssl_key {
        validate_path_input(key, "ssl_key")?;
    }

    // 4. Custom headers validation
    for h in &ctx.custom_headers {
        if !h
            .name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid HTTP header name: '{}'",
                h.name
            )));
        }
        if h.value
            .chars()
            .any(|c| c == '\n' || c == '\r' || c == '\0' || c == '"' || c == ';')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid characters in HTTP header value: '{}'",
                h.value
            )));
        }
    }

    // 5. Redirects validation
    for r in &ctx.redirects {
        validate_domain_input(&r.domain)?;
        validate_redirect_target(&r.target)?;
        if r.status_code != 301
            && r.status_code != 302
            && r.status_code != 307
            && r.status_code != 308
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid redirect status code: {}",
                r.status_code
            )));
        }
    }

    // 6. PHP version validation (e.g. 7.4, 8.0, 8.1, 8.2, 8.3, 8.4)
    if ctx.php_version.trim().is_empty()
        || !ctx
            .php_version
            .chars()
            .all(|c| c.is_ascii_digit() || c == '.')
        || !ctx.php_version.contains('.')
    {
        return Err(WebserverError::SecurityViolation(format!(
            "Invalid PHP version '{}'",
            ctx.php_version
        )));
    }

    // 7. FPM Socket validation
    validate_socket_input(&ctx.fpm_socket, "fpm_socket")?;

    // 8. Upload max size validation (e.g. "64M", "100M", "10M", "2G", "1024")
    if let Some(ref upload) = ctx.upload_max_size {
        validate_upload_size_input(upload)?;
    }

    // 9. Custom entry file validation
    if let Some(ref entry) = ctx.custom_entry_file {
        validate_entry_file_input(entry)?;
    }

    // 10. FastCGI cache validation
    if let Some(ref cache) = ctx.fastcgi_cache {
        if cache.enabled {
            if let Some(ref zone) = cache.zone_name {
                if !zone.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
                    return Err(WebserverError::SecurityViolation(format!(
                        "Invalid cache zone name: '{zone}'"
                    )));
                }
            }
            if let Some(ref valid) = cache.valid_time {
                if !valid
                    .chars()
                    .all(|c| c.is_ascii_digit() || matches!(c, 's' | 'm' | 'h' | 'd'))
                {
                    return Err(WebserverError::SecurityViolation(format!(
                        "Invalid cache valid time: '{valid}'"
                    )));
                }
            }
            for cookie in &cache.custom_bypass_cookies {
                if !cookie
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
                {
                    return Err(WebserverError::SecurityViolation(format!(
                        "Invalid bypass cookie name: '{cookie}'"
                    )));
                }
            }
        }
    }

    Ok(())
}

fn validate_socket_input(raw: &str, field_name: &str) -> Result<(), WebserverError> {
    if raw.trim().is_empty() {
        return Err(WebserverError::SecurityViolation(format!(
            "{field_name} cannot be empty"
        )));
    }
    const FORBIDDEN_CHARS: &[char] = &[';', '{', '}', '$', '\n', '\r', '\0', '"', ' '];
    for ch in FORBIDDEN_CHARS {
        if raw.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "{field_name} contains forbidden character '{ch}'"
            )));
        }
    }
    if !raw.starts_with("unix:") && !raw.starts_with('/') {
        return Err(WebserverError::SecurityViolation(format!(
            "{field_name} must start with 'unix:' or '/'"
        )));
    }
    Ok(())
}

fn validate_upload_size_input(raw: &str) -> Result<(), WebserverError> {
    let s = raw.trim();
    if s.is_empty() {
        return Err(WebserverError::SecurityViolation(
            "upload_max_size cannot be empty".to_string(),
        ));
    }
    let digits = s.trim_end_matches(['k', 'K', 'm', 'M', 'g', 'G']);
    if digits.is_empty() || !digits.chars().all(|c| c.is_ascii_digit()) {
        return Err(WebserverError::SecurityViolation(format!(
            "Invalid upload_max_size: '{raw}'"
        )));
    }
    Ok(())
}

fn validate_entry_file_input(raw: &str) -> Result<(), WebserverError> {
    let s = raw.trim();
    if s.is_empty() {
        return Err(WebserverError::SecurityViolation(
            "custom_entry_file cannot be empty".to_string(),
        ));
    }
    if s.contains('/') || s.contains('\\') || s.contains("..") {
        return Err(WebserverError::SecurityViolation(format!(
            "custom_entry_file '{raw}' must not contain path separators or traversal"
        )));
    }
    if !s
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '.' || c == '_' || c == '-')
    {
        return Err(WebserverError::SecurityViolation(format!(
            "custom_entry_file '{raw}' contains invalid characters"
        )));
    }
    Ok(())
}

