    #[test]
    fn test_anti_injection_rejects_malicious_domains() {
        let renderer = NginxTemplateRenderer::new();
        let malicious_domains = vec![
            "example.com; return 403;",
            "evil.com\nserver { listen 8888; }",
            "evil.com\r\nlocation / { proxy_pass http://attacker; }",
            "test.com{root /;}",
            "attacker.com$document_root",
            "foo.com\"evil",
            "foo bar.com",
            "evil.com\0payload",
        ];

        for bad in malicious_domains {
            let ctx = StaticVhostContext {
                site_id: "site_test".to_string(),
                primary_domain: bad.to_string(),
                alias_domains: vec![],
                redirects: vec![],
                docroot: "/home/p_alice/public".to_string(),
                log_dir: "/var/log/panel/site".to_string(),
                snippets_dir: "/etc/panel/nginx/snippets".to_string(),
                index_files: None,
                spa_fallback: false,
                has_ssl: false,
                ssl_cert: None,
                ssl_key: None,
                force_https: false,
                ocsp_stapling: false,
                custom_headers: vec![],
            };

            let err = renderer.render_static(&ctx);
            assert!(
                err.is_err(),
                "Malicious domain '{}' should have been rejected!",
                bad
            );
        }
    }

